import React, { createContext, useState, useEffect, useContext } from 'react';
import api from '../utils/api';

// 1. Create the Context
export const AuthContext = createContext();

// 2. Create the Provider Component
export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [token, setToken] = useState(localStorage.getItem('token'));

  const setAuthSession = (userData, authToken) => {
    localStorage.setItem('token', authToken);
    localStorage.setItem('user', JSON.stringify(userData));
    setToken(authToken);
    setUser(userData);
  };

  useEffect(() => {
    // Check if user is already logged in
    if (token) {
      fetchProfile();
    } else {
      setLoading(false);
    }
  }, [token]);

  const fetchProfile = async () => {
    try {
      const response = await api.get('/auth/profile');
      setUser(response.data);
    } catch (error) {
      console.error('Failed to fetch profile:', error);
      localStorage.removeItem('token');
      setToken(null);
      setUser(null);
    } finally {
      setLoading(false);
    }
  };

  const login = async (email, password) => {
    const response = await api.post('/auth/login', { email, password });
    const { token: receivedToken, user: userData } = response.data;
    localStorage.setItem('token', receivedToken);
    setToken(receivedToken);
    setUser(userData);
    return userData;
  };

  const register = async (email, password, firstName, lastName, isHost) => {
    try {
      const response = await api.post('/auth/register', {
        email,
        password,
        firstName,
        lastName,
        isHost,
      });
      
      // Rename destructured property here as well
      const { token: receivedToken, user: userData } = response.data;
      
      localStorage.setItem('token', receivedToken);
      setToken(receivedToken);
      setUser(userData);
      
      return userData;
    } catch (error) {
      throw error;
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    setToken(null);
    setUser(null);
  };

  const updateProfile = async (profileData) => {
    try {
      const response = await api.put('/auth/profile', profileData);
      setUser(response.data);
      return response.data;
    } catch (error) {
      throw error;
    }
  };

  // Safe context object configurations
  const value = {
    user: user && typeof user === 'object' ? user : null,
    token: token || null,
    loading: !!loading,
    login,
    setAuthSession,
    register,
    logout,
    updateProfile,
    isAuthenticated: Boolean(token),
    isHost: user && typeof user === 'object' ? Boolean(user.isHost) : false, 
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

// 3. Create and Export the Custom Hook
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { useState, useEffect } from 'react';
import { useAdmin } from '../context/AdminContext';
import { AdminLayout } from '../components/AdminLayout';
import UserDetailsModal from '../components/UserDetailsModal';
import AdminMessageModal from '../components/AdminMessageModal';
import MessageBanner from '../components/MessageBanner';
import '../styles/admin.css';

export const AdminUsers = () => {
  const { fetchUsers, suspendUser, unsuspendUser, deleteUser, loading, error } = useAdmin();
  
  const [users, setUsers] = useState([]);
  const [localError, setLocalError] = useState(null);
  const [pagination, setPagination] = useState({});
  const [currentPage, setCurrentPage] = useState(1);
  const [search, setSearch] = useState('');
  const [role, setRole] = useState('');
  const [status, setStatus] = useState('');
  const [selectedUser, setSelectedUser] = useState(null);
  const [modalActive, setModalActive] = useState(false);
  const [actionType, setActionType] = useState(null);
  const [reason, setReason] = useState('');
  const [successMessage, setSuccessMessage] = useState('');
  
  // New modals for Phase 5C
  const [detailsModalOpen, setDetailsModalOpen] = useState(false);
  const [messageModalOpen, setMessageModalOpen] = useState(false);
  const [detailsUser, setDetailsUser] = useState(null);
  const [messageUser, setMessageUser] = useState(null);
  const [confirm, setConfirm] = useState({ open: false, title: '', message: '', onConfirm: null });

  const loadUsers = async (page = 1, filters = {}) => {
    const result = await fetchUsers(page, 20, filters);
    if (result) {
      setUsers(result.users);
      setPagination(result.pagination);
    }
  };

  useEffect(() => {
    loadUsers(1, { search, role, status });
  }, [search, role, status]);

  const handleSuspend = async () => {
    if (!selectedUser || !reason) {
      setLocalError('Please enter a reason');
      return;
    }
    setLocalError(null);
    const result = await suspendUser(selectedUser._id, reason);
    if (result) {
      setSuccessMessage(`User ${selectedUser.email} suspended`);
      setModalActive(false);
      setReason('');
      loadUsers(currentPage, { search, role, status });
      setTimeout(() => setSuccessMessage(''), 3000);
    }
  };

  const handleUnsuspend = async () => {
    if (!selectedUser) return;
    
    const result = await unsuspendUser(selectedUser._id);
    if (result) {
      setSuccessMessage(`User ${selectedUser.email} unsuspended`);
      setModalActive(false);
      loadUsers(currentPage, { search, role, status });
      setTimeout(() => setSuccessMessage(''), 3000);
    }
  };

  const handleDelete = () => {
    if (!selectedUser || !reason) {
      setLocalError('Please enter a reason');
      return;
    }

    setConfirm({
      open: true,
      title: 'Delete User',
      message: 'Are you sure? This action cannot be undone.',
      onConfirm: async () => {
        setConfirm({ open: false });
        setLocalError(null);
        const result = await deleteUser(selectedUser._id, reason);
        if (result) {
          setSuccessMessage(`User ${selectedUser.email} deleted`);
          setModalActive(false);
          setReason('');
          loadUsers(1, { search, role, status });
          setTimeout(() => setSuccessMessage(''), 3000);
        }
      },
    });
  };

  const openModal = (user, type) => {
    setSelectedUser(user);
    setActionType(type);
    setReason('');
    setModalActive(true);
  };

  const closeModal = () => {
    setModalActive(false);
    setSelectedUser(null);
    setActionType(null);
    setReason('');
  };

  // New handler for different action types from UserDetailsModal
  const handleModalAction = (action, user) => {
    if (action === 'suspend') {
      openModal(user, 'suspend');
    } else if (action === 'unsuspend') {
      openModal(user, 'unsuspend');
    } else if (action === 'delete') {
      openModal(user, 'delete');
    } else if (action === 'message') {
      setMessageUser(user);
      setMessageModalOpen(true);
    }
    setDetailsModalOpen(false);
  };

  const openDetailsModal = (user) => {
    setDetailsUser(user);
    setDetailsModalOpen(true);
  };

  if (loading) {
    return (
      <AdminLayout>
        <div className="loading">
          <div className="loading-spinner"></div>
          <p>Loading users...</p>
        </div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout>
      <div className="admin-page">
        <h1>User Management</h1>

        {localError && (
          <MessageBanner
            type="error"
            title="Action required"
            message={localError}
            onClose={() => setLocalError(null)}
          />
        )}
        {error && (
          <MessageBanner
            type="error"
            title="Failed to manage users"
            message={error}
            onClose={() => {}}
          />
        )}
        {successMessage && (
          <MessageBanner
            type="success"
            title="Success"
            message={successMessage}
            onClose={() => setSuccessMessage('')}
          />
        )}

        <ConfirmDialog
          open={confirm.open}
          title={confirm.title}
          message={confirm.message}
          onConfirm={confirm.onConfirm}
          onCancel={() => setConfirm({ open: false })}
        />

        {/* Filters */}
        <div className="search-bar">
          <input
            type="text"
            placeholder="Search by email or name..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="search-input"
          />
          <select value={role} onChange={(e) => setRole(e.target.value)} className="search-input">
            <option value="">All Roles</option>
            <option value="student">Students</option>
            <option value="host">Hosts</option>
          </select>
          <select value={status} onChange={(e) => setStatus(e.target.value)} className="search-input">
            <option value="">All Status</option>
            <option value="active">Active</option>
            <option value="suspended">Suspended</option>
            <option value="banned">Banned</option>
          </select>
        </div>

        {/* Users Table */}
        <div className="admin-table">
          <table>
            <thead>
              <tr>
                <th>Email</th>
                <th>Name</th>
                <th>Role</th>
                <th>Status</th>
                <th>Joined</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {users.map((user) => (
                <tr key={user._id}>
                  <td>{user.email}</td>
                  <td>{`${user.firstName || ''} ${user.lastName || ''}`.trim() || 'N/A'}</td>
                  <td>
                    {user.isHost && <span className="status-badge active">Host</span>}
                    {user.isStudent && <span className="status-badge pending">Student</span>}
                  </td>
                  <td>
                    {user.bannedAt ? (
                      <span className="status-badge banned">Banned</span>
                    ) : user.suspendedAt ? (
                      <span className="status-badge suspended">Suspended</span>
                    ) : (
                      <span className="status-badge active">Active</span>
                    )}
                  </td>
                  <td>{new Date(user.createdAt).toLocaleDateString()}</td>
                  <td>
                    <button
                      className="btn btn-info btn-sm"
                      onClick={() => openDetailsModal(user)}
                      title="View details and activity"
                    >
                      Details
                    </button>
                    {user.suspendedAt ? (
                      <button
                        className="btn btn-success btn-sm"
                        onClick={() => openModal(user, 'unsuspend')}
                      >
                        Unsuspend
                      </button>
                    ) : (
                      <button
                        className="btn btn-primary btn-sm"
                        onClick={() => openModal(user, 'suspend')}
                      >
                        Suspend
                      </button>
                    )}
                    {!user.bannedAt && (
                      <button
                        className="btn btn-danger btn-sm"
                        onClick={() => openModal(user, 'delete')}
                      >
                        Delete
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {pagination.pages > 1 && (
          <div className="pagination">
            {Array.from({ length: pagination.pages }, (_, i) => i + 1).map((page) => (
              <button
                key={page}
                className={page === currentPage ? 'active' : ''}
                onClick={() => {
                  setCurrentPage(page);
                  loadUsers(page, { search, role, status });
                }}
              >
                {page}
              </button>
            ))}
          </div>
        )}

        {/* Action Modal */}
        <div className={`modal ${modalActive ? 'active' : ''}`}>
          <div className="modal-content">
            <div className="modal-header">
              {actionType === 'suspend' && `Suspend User - ${selectedUser?.email}`}
              {actionType === 'unsuspend' && `Unsuspend User - ${selectedUser?.email}`}
              {actionType === 'delete' && `Delete User - ${selectedUser?.email}`}
            </div>
            <div className="modal-body">
              {(actionType === 'suspend' || actionType === 'delete') && (
                <div className="form-group">
                  <label>Reason</label>
                  <textarea
                    value={reason}
                    onChange={(e) => setReason(e.target.value)}
                    placeholder="Enter reason for this action..."
                  />
                </div>
              )}
              {actionType === 'unsuspend' && (
                <p>Are you sure you want to unsuspend this user? They will regain access to their account.</p>
              )}
            </div>
            <div className="modal-footer">
              <button className="btn" onClick={closeModal}>
                Cancel
              </button>
              {actionType === 'suspend' && (
                <button className="btn btn-warning" onClick={handleSuspend}>
                  Suspend User
                </button>
              )}
              {actionType === 'unsuspend' && (
                <button className="btn btn-success" onClick={handleUnsuspend}>
                  Unsuspend User
                </button>
              )}
              {actionType === 'delete' && (
                <button className="btn btn-danger" onClick={handleDelete}>
                  Delete User
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Phase 5C: User Details Modal */}
        <UserDetailsModal
          user={detailsUser}
          isOpen={detailsModalOpen}
          onClose={() => setDetailsModalOpen(false)}
          onAction={handleModalAction}
        />

        {/* Phase 5C: Admin Message Modal */}
        <AdminMessageModal
          user={messageUser}
          isOpen={messageModalOpen}
          onClose={() => setMessageModalOpen(false)}
          onSuccess={() => {
            setSuccessMessage('Message sent successfully!');
            setTimeout(() => setSuccessMessage(''), 3000);
          }}
        />
      </div>
    </AdminLayout>
  );
};

/**
 * PWA - Offline Indicator Component
 * Shows when user is offline with sync status
 */

export const createOfflineIndicator = () => {
  const style = `
    .offline-indicator {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      background: #ff6b6b;
      color: white;
      padding: 12px 16px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      font-size: 14px;
      font-weight: 500;
      z-index: 9999;
      animation: slideDown 0.3s ease-out;
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    }

    .offline-indicator.online {
      background: #51cf66;
    }

    .offline-indicator__content {
      display: flex;
      align-items: center;
      gap: 8px;
      flex: 1;
    }

    .offline-indicator__status {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .offline-indicator__icon {
      font-size: 16px;
      animation: pulse 1.5s ease-in-out infinite;
    }

    .offline-indicator.online .offline-indicator__icon {
      animation: none;
    }

    .offline-indicator__message {
      flex: 1;
    }

    .offline-indicator__action {
      background: rgba(255, 255, 255, 0.2);
      border: none;
      color: white;
      padding: 6px 12px;
      border-radius: 4px;
      cursor: pointer;
      font-size: 12px;
      font-weight: 600;
      transition: background 0.2s;
    }

    .offline-indicator__action:hover {
      background: rgba(255, 255, 255, 0.3);
    }

    .offline-indicator__sync {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 12px;
    }

    .offline-indicator__sync-spinner {
      width: 12px;
      height: 12px;
      border: 2px solid rgba(255, 255, 255, 0.3);
      border-top-color: white;
      border-radius: 50%;
      animation: spin 0.8s linear infinite;
    }

    @keyframes slideDown {
      from {
        transform: translateY(-100%);
        opacity: 0;
      }
      to {
        transform: translateY(0);
        opacity: 1;
      }
    }

    @keyframes pulse {
      0%, 100% {
        opacity: 1;
      }
      50% {
        opacity: 0.5;
      }
    }

    @keyframes spin {
      to {
        transform: rotate(360deg);
      }
    }

    /* Adjust main content when indicator is visible */
    body.offline-active main,
    body.offline-active .app-content {
      margin-top: 48px;
    }
  `;

  const html = `
    <div class="offline-indicator offline" id="offline-indicator">
      <div class="offline-indicator__content">
        <div class="offline-indicator__status">
          <span class="offline-indicator__icon">📡</span>
          <span class="offline-indicator__message">You're offline • Changes will be synced</span>
        </div>
      </div>
      <button class="offline-indicator__action" id="sync-now">
        Sync Now
      </button>
    </div>
  `;

  const syncIndicatorHtml = `
    <div class="offline-indicator__sync" id="sync-status" style="display: none;">
      <span class="offline-indicator__sync-spinner"></span>
      <span>Syncing...</span>
    </div>
  `;

  return {
    style,
    html,
    syncIndicatorHtml,
  };
};

/**
 * Offline Indicator Script
 */
export const offlineIndicatorScript = `
(function() {
  const indicator = document.getElementById('offline-indicator');
  const syncBtn = document.getElementById('sync-now');
  const syncStatus = document.getElementById('sync-status');

  if (!indicator) return;

  // Update indicator status
  function updateStatus() {
    const isOnline = navigator.onLine;
    
    if (isOnline) {
      indicator.classList.remove('offline');
      indicator.classList.add('online');
      indicator.querySelector('.offline-indicator__message').textContent = 
        'You\'re online • All changes synced';
      
      // Hide after 3 seconds
      setTimeout(() => {
        indicator.style.opacity = '0';
        indicator.style.pointerEvents = 'none';
        setTimeout(() => {
          indicator.style.display = 'none';
        }, 300);
      }, 3000);
    } else {
      indicator.classList.remove('online');
      indicator.classList.add('offline');
      indicator.style.display = 'flex';
      indicator.style.opacity = '1';
      indicator.style.pointerEvents = 'auto';
      document.body.classList.add('offline-active');
    }
  }

  // Listen for online/offline events
  window.addEventListener('online', updateStatus);
  window.addEventListener('offline', updateStatus);

  // Sync button handler
  if (syncBtn) {
    syncBtn.addEventListener('click', async () => {
      syncStatus.style.display = 'flex';
      syncBtn.disabled = true;
      
      try {
        // Call offline queue sync
        if (window.offlineQueueService && window.offlineQueueService.processQueue) {
          const result = await window.offlineQueueService.processQueue();
          
          if (result.failed === 0) {
            updateStatus();
          }
        }
      } catch (error) {
        console.error('Sync failed:', error);
      } finally {
        syncStatus.style.display = 'none';
        syncBtn.disabled = false;
      }
    });
  }

  // Initial status
  updateStatus();
})();
`;

/**
 * Inject offline indicator into page
 */
export const injectOfflineIndicator = () => {
  // Create styles
  const styleEl = document.createElement('style');
  styleEl.textContent = createOfflineIndicator().style;
  document.head.appendChild(styleEl);

  // Create HTML
  const container = document.createElement('div');
  container.innerHTML = createOfflineIndicator().html;
  document.body.insertBefore(container.firstChild, document.body.firstChild);

  // Execute script
  const script = document.createElement('script');
  script.textContent = offlineIndicatorScript;
  document.body.appendChild(script);

  console.log('✓ Offline indicator injected');
};

// Testing utilities for PWA features and performance
// Import with: import { testAllFeatures } from './testHelpers';

export const testHelpers = {
  /**
   * Detect browser PWA capabilities
   */
  detectCapabilities: () => {
    const capabilities = {
      serviceWorker: 'serviceWorker' in navigator,
      pushManager: 'PushManager' in window,
      notification: 'Notification' in window,
      indexedDB: 'indexedDB' in window,
      localStorage: 'localStorage' in window,
      cacheAPI: 'caches' in window,
      periodicSync: (typeof ServiceWorkerRegistration !== 'undefined' && ServiceWorkerRegistration.prototype && 'periodicSync' in ServiceWorkerRegistration.prototype) || false,
      backgroundSync: (typeof ServiceWorkerRegistration !== 'undefined' && ServiceWorkerRegistration.prototype && 'sync' in ServiceWorkerRegistration.prototype) || false,
      sharedStorage: 'sharedStorage' in window,
    };

    return capabilities;
  },

  /**
   * Get browser info
   */
  getBrowserInfo: () => {
    const ua = navigator.userAgent;
    return {
      userAgent: ua,
      isChrome: /Chrome/.test(ua) && !/Chromium/.test(ua),
      isChromium: /Chromium/.test(ua),
      isFirefox: /Firefox/.test(ua),
      isSafari: /Safari/.test(ua) && !/Chrome/.test(ua),
      isEdge: /Edg/.test(ua),
      isOpera: /OPR/.test(ua),
      isMobile: /Mobile/.test(ua),
      isTablet: /Tablet/.test(ua),
      isIOS: /iPhone|iPad/.test(ua),
      isAndroid: /Android/.test(ua),
      isWindows: /Windows/.test(ua),
      isMac: /Macintosh/.test(ua),
      isLinux: /Linux/.test(ua),
    };
  },

  /**
   * Test API endpoints
   */
  testAPIEndpoints: async () => {
    const endpoints = [
      { method: 'GET', path: '/api/auth/profile', requiresAuth: true },
      { method: 'GET', path: '/api/classes', requiresAuth: false },
      { method: 'GET', path: '/api/push/subscriptions', requiresAuth: true },
    ];

    const results = [];
    for (const endpoint of endpoints) {
      try {
        const apiBase = import.meta?.env?.VITE_API_URL || 'http://localhost:5001';
                const response = await fetch(`${apiBase.replace(/\/\/$/, '')}${endpoint.path}`);
        results.push({
          endpoint: endpoint.path,
          status: response.status,
          ok: response.ok,
          statusText: response.statusText,
        });
      } catch (error) {
        results.push({
          endpoint: endpoint.path,
          error: error.message,
          status: 'FAILED',
        });
      }
    }

    return results;
  },

  /**
   * Measure performance metrics
   */
  measurePerformance: () => {
    const metrics = {
      navigationTiming: {},
      resourceTiming: [],
      memoryUsage: {},
    };

    // Navigation timing
    if (performance.timing) {
      const timing = performance.timing;
      metrics.navigationTiming = {
        dns: timing.domainLookupEnd - timing.domainLookupStart,
        tcp: timing.connectEnd - timing.connectStart,
        ttfb: timing.responseStart - timing.requestStart,
        download: timing.responseEnd - timing.responseStart,
        domParse: timing.domComplete - timing.domLoading,
        dcl: timing.domContentLoadedEventEnd - timing.navigationStart,
        load: timing.loadEventEnd - timing.navigationStart,
      };
    }

    // Resource timing (first 10)
    if (performance.getEntriesByType) {
      metrics.resourceTiming = performance
        .getEntriesByType('resource')
        .slice(0, 10)
        .map((r) => ({
          name: r.name.split('/').pop(),
          duration: Math.round(r.duration),
          size: r.transferSize || 0,
        }));
    }

    // Memory usage (if available)
    if (performance.memory) {
      metrics.memoryUsage = {
        usedJSHeapSize: Math.round(
          performance.memory.usedJSHeapSize / 1024 / 1024
        ),
        totalJSHeapSize: Math.round(
          performance.memory.totalJSHeapSize / 1024 / 1024
        ),
        jsHeapSizeLimit: Math.round(
          performance.memory.jsHeapSizeLimit / 1024 / 1024
        ),
      };
    }

    return metrics;
  },

  /**
   * Test Service Worker installation
   */
  testServiceWorker: async () => {
    if (!('serviceWorker' in navigator)) {
      return { installed: false, error: 'Service Worker not supported' };
    }

    try {
      const registration = await navigator.serviceWorker.getRegistration();
      return {
        installed: !!registration,
        active: registration?.active ? true : false,
        scope: registration?.scope || 'N/A',
        updateViaCache:
          registration?.updateViaCache || 'N/A',
      };
    } catch (error) {
      return { installed: false, error: error.message };
    }
  },

  /**
   * Test cache storage
   */
  testCacheStorage: async () => {
    if (!('caches' in window)) {
      return { available: false, error: 'Cache API not supported' };
    }

    try {
      const cacheNames = await caches.keys();
      const cacheDetails = [];

      for (const name of cacheNames) {
        const cache = await caches.open(name);
        const requests = await cache.keys();
        cacheDetails.push({
          name,
          itemCount: requests.length,
          items: requests.slice(0, 5).map((r) => r.url.split('/').pop()),
        });
      }

      return {
        available: true,
        cacheCount: cacheNames.length,
        caches: cacheDetails,
      };
    } catch (error) {
      return { available: false, error: error.message };
    }
  },

  /**
   * Test IndexedDB storage
   */
  testIndexedDB: async () => {
    if (!('indexedDB' in window)) {
      return { available: false, error: 'IndexedDB not supported' };
    }

    try {
      const dbs = await indexedDB.databases?.();
      return {
        available: true,
        databaseCount: dbs?.length || 0,
        databases: dbs?.map((db) => db.name) || [],
      };
    } catch (error) {
      return { available: false, error: error.message };
    }
  },

  /**
   * Test notification permission
   */
  testNotificationPermission: () => {
    if (!('Notification' in window)) {
      return {
        supported: false,
        error: 'Notification API not supported',
      };
    }

    return {
      supported: true,
      permission: Notification.permission,
      canRequest:
        Notification.permission === 'default',
    };
  },

  /**
   * Run all tests
   */
  runAllTests: async () => {
    console.log('🧪 Starting PWA Feature Tests...\n');

    const results = {
      timestamp: new Date().toISOString(),
      browser: testHelpers.getBrowserInfo(),
      capabilities: testHelpers.detectCapabilities(),
      serviceWorker: await testHelpers.testServiceWorker(),
      cacheStorage: await testHelpers.testCacheStorage(),
      indexedDB: await testHelpers.testIndexedDB(),
      notifications: testHelpers.testNotificationPermission(),
      performance: testHelpers.measurePerformance(),
      endpoints: await testHelpers.testAPIEndpoints(),
    };

    console.log('✅ Test Results:');
    console.table(results);

    return results;
  },

  /**
   * Log results in human-readable format
   */
  logResults: (results) => {
    console.log('\n📊 PWA Feature Test Results\n');
    console.log('Browser:', results.browser);
    console.log('\nCapabilities:');
    Object.entries(results.capabilities).forEach(([key, value]) => {
      console.log(`  ${key}: ${value ? '✅' : '❌'}`);
    });

    console.log('\nService Worker:', results.serviceWorker);
    console.log('Cache Storage:', results.cacheStorage);
    console.log('IndexedDB:', results.indexedDB);
    console.log('Notifications:', results.notifications);

    console.log('\nPerformance Metrics:');
    if (results.performance.navigationTiming) {
      Object.entries(results.performance.navigationTiming).forEach(
        ([key, value]) => {
          console.log(`  ${key}: ${Math.round(value)}ms`);
        }
      );
    }

    if (results.performance.memoryUsage.usedJSHeapSize) {
      console.log(
        `  Memory Usage: ${results.performance.memoryUsage.usedJSHeapSize}MB / ${results.performance.memoryUsage.totalJSHeapSize}MB`
      );
    }

    console.log('\nAPI Endpoints:');
    results.endpoints.forEach((endpoint) => {
      const status = endpoint.ok ? '✅' : '❌';
      console.log(
        `  ${status} ${endpoint.endpoint}: ${endpoint.status || endpoint.error}`
      );
    });
  },
};

// For quick testing, export individual functions
export const {
  detectCapabilities,
  getBrowserInfo,
  testAPIEndpoints,
  measurePerformance,
  testServiceWorker,
  testCacheStorage,
  testIndexedDB,
  testNotificationPermission,
  runAllTests,
  logResults,
} = testHelpers;

